def recv_exact(conn, size):
    "Read exactly `size` bytes: `recv` may return less than requested."
    buf = bytearray()
    while len(buf) < size:
        chunk = conn.recv(size - len(buf))
        if not chunk:
            raise ConnectionError("OpenPlanet closed the connection")
        buf += chunk
    return bytes(buf)


class SimpleValueParser:
    def __init__(self, name, format):
        store_attr()
        self.struct = struct.Struct(format)

    def __call__(self, conn):
        (value,) = self.struct.unpack(recv_exact(conn, self.struct.size))
        return self.name, value


class ListValueParser:
    def __init__(self, name, format):
        store_attr()
        self.structs = [struct.Struct(f) for f in format]

    def __call__(self, conn):
        values = []
        for s in self.structs:
            (value,) = s.unpack(recv_exact(conn, s.size))
            values.append(value)
        return self.name, values


def build_parser(name, format):
    if isinstance(format, list):
        return ListValueParser(name, format)
    return SimpleValueParser(name, format)


class TelemetryParser:
    def __init__(self, conn):
        store_attr()
        self.config = json.loads(self._read_header(conn), object_pairs_hook=OrderedDict)
        logging.debug("Telemetry parser config received.")
        self.parsers = L(build_parser(*item) for item in self.config.items())
        # The whole frame is decoded with a single struct (little endian, no padding)
        self.names, self.lengths, formats = [], [], []
        for name, fmt in self.config.items():
            fmts = fmt if isinstance(fmt, list) else [fmt]
            self.names.append(name)
            self.lengths.append(len(fmts) if isinstance(fmt, list) else 0)
            formats.extend(fmts)
        self.frame = struct.Struct("<" + "".join(formats))

    @staticmethod
    def _read_header(conn):
        # The header is a flat JSON object (no nested braces) sent right before the binary frames
        header = bytearray()
        while not header.endswith(b"}"):
            header += recv_exact(conn, 1)
        return header.decode()

    def __call__(self):
        values = self.frame.unpack(recv_exact(self.conn, self.frame.size))
        telemetry, i = {}, 0
        for name, length in zip(self.names, self.lengths):
            if length:
                telemetry[name] = list(values[i : i + length])
                i += length
            else:
                telemetry[name] = values[i]
                i += 1
        telemetry["_updatetime"] = time()
        return telemetry

