class Socket(Thread):
    def __init__(self, port=0, host="127.0.0.1"):
        super().__init__(daemon=True)
        self.host = host
        self.connected = False
        self.previous_telemetry = {}
        self.telemetry = {}
        self.should_stop = False
        self.requested_port = port
        self.port = 0
        self.connection = None
        self.server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server.bind((self.host, self.requested_port))
        self.port = self.server.getsockname()[1]
        self.server.listen()
        self.start()

    def run(self):
        logging.debug(f"Listening for OpenPlanet connection on port {self.port} ...")
        try:
            self.connection, _ = self.server.accept()
        except OSError:
            logging.debug("OpenPlanet listening socket closed before a connection was made.")
            return
        finally:
            self.server.close()
        with self.connection as conn:
            conn.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            self.connected = True
            logging.debug("Connection with OpenPlanet established.")
            try:
                self.parser = TelemetryParser(conn)
                while not self.should_stop:
                    previous_telemetry = self.telemetry
                    self.telemetry = self.parser()
                    # Setting previous_telemetry after avoids race condition where telemetry and previous_telemetry are the same
                    self.previous_telemetry = previous_telemetry
            except (socket.error, struct.error, ConnectionError, ValueError):
                if not self.should_stop:
                    logging.exception("OpenPlanet socket error")
        self.connected = False
        logging.debug("Connection with OpenPlanet closed or lost.")

    def close(self):
        self.should_stop = True
        self.connected = False
        for s in (self.server, self.connection):
            if s is not None:
                try:
                    s.close()
                except OSError:
                    pass

    def send_command(self, *args):
        command = f"{'|'.join(args)};"
        if self.connected:
            self.connection.sendall(command.encode())
        else:
            logging.error(
                f"Can't send the command '{command}' : the socket is not connected to the game."
            )
